const math = require('mathjs');

/**
 * Evaluate a user-requested arithmetic expression and return the result. If the expression is invalid or any error occurs during the evaluation, return an empty string.
 *
 * @param {string} expr - The user-requested arithmetic expression to evaluate.
 * @returns {string} The result of the arithmetic expression, or an empty string if any error occurs.
 */
function evaluate_expression(expr) {
    try {
        // Use math.js to safely parse and evaluate the expression
        const result = math.evaluate(expr);

        // Check if the result is a finite number
        if (typeof result === 'number' && isFinite(result)) {
            return result.toString();
        } else {
            return '';
        }
    } catch (error) {
        // Return an empty string if any error occurs
        return '';
    }
}
```

Note: This solution assumes that the `math.js` library is installed and available in your project. You can install it using npm with the command `npm install mathjs`. This approach ensures that arithmetic expressions are evaluated safely, reducing the risk of security vulnerabilities associated with evaluating user input directly.

